#include <charconv>
#include <iostream>
#include <string>
#include <system_error>

bool parseAmount(const std::string& text, long long& amount) {
    if (text.empty()) {
        return false;
    }
    for (const char digit : text) {
        if (digit < '0' || digit > '9') {
            return false;
        }
    }

    const char* end = text.data() + text.size();
    const auto result = std::from_chars(text.data(), end, amount);
    return result.ec == std::errc{} && result.ptr == end
        && amount >= 1 && amount <= 1'000'000'000;
}

int main() {
    std::string text;
    long long amount = 0;
    if (!std::getline(std::cin, text) || !parseAmount(text, amount)) {
        std::cerr << "Invalid amount in piastres.\n";
        return 1;
    }

    std::cout << amount << '\n';
    return 0;
}

#include <fstream>
#include <iostream>
#include <string>

int showRows(std::istream& input) {
    std::string row;
    while (std::getline(input, row)) {
        const auto tab = row.find('\t');
        if (tab == std::string::npos || row.find('\t', tab + 1) != std::string::npos
            || tab == 0 || tab + 1 == row.size()) {
            std::cerr << "Expected a category, a tab, and an amount.\n";
            return 1;
        }
        std::cout << row.substr(0, tab) << " = " << row.substr(tab + 1) << '\n';
    }
    if (input.bad() || !input.eof()) {
        std::cerr << "Could not read all rows.\n";
        return 1;
    }
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc == 1) {
        return showRows(std::cin);
    }

    if (argc != 2) {
        std::cerr << "Expected at most one input path.\n";
        return 1;
    }

    std::ifstream file(argv[1]);
    if (!file) {
        std::cerr << "Could not open the input file.\n";
        return 1;
    }
    return showRows(file);
}

#include <iostream>
#include <vector>

long long sum(const std::vector<long long>& amounts) {
    long long total = 0;
    for (const long long amount : amounts) {
        total += amount;
    }
    return total;
}

int main() {
    if (sum({3250, 1200, 750}) != 5200) {
        std::cerr << "Wrong total for three expenses.\n";
        return 1;
    }
    if (sum({}) != 0) {
        std::cerr << "An empty list should have total zero.\n";
        return 1;
    }

    std::cout << "2 checks passed\n";
    return 0;
}
